interface PricingStrategy { double priceFor(Ticket t, Duration d); }
interface SpotAllocation { Optional<ParkingSpot> claim(Vehicle v); }

class ParkingSpot {
  final String id; final SpotType type;
  private volatile boolean occupied; // claimed atomically via manager
  ParkingSpot(String id, SpotType type) { this.id = id; this.type = type; }
}

class Ticket {
  final String id; final Vehicle vehicle; final ParkingSpot spot;
  final Instant entryAt; Instant exitAt;
  Ticket(String id, Vehicle v, ParkingSpot s, Instant t) {
    this.id = id; this.vehicle = v; this.spot = s; this.entryAt = t;
  }
}

class ParkingLot {
  private final SpotAllocation allocator;
  private final PricingStrategy pricing;
  private final Map<String, Ticket> active = new ConcurrentHashMap<>();
  ParkingLot(SpotAllocation a, PricingStrategy p) { this.allocator = a; this.pricing = p; }
  public Ticket park(Vehicle v) {
    ParkingSpot s = allocator.claim(v).orElseThrow(() -> new IllegalStateException("full"));
    Ticket t = new Ticket(UUID.randomUUID().toString(), v, s, Instant.now());
    active.put(t.id, t);
    return t;
  }
  public double unpark(String ticketId) {
    Ticket t = active.remove(ticketId);
    if (t == null) throw new IllegalArgumentException("bad ticket");
    t.exitAt = Instant.now();
    return pricing.priceFor(t, Duration.between(t.entryAt, t.exitAt));
  }
}

